{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; its absence cannot be assumed."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring are described for a narrow grid-puzzle comparison. The reported score describes one run; repeatability and evidence supporting comparisons beyond that run remain unknown."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated results, stability is untested; this does not demonstrate unstable scores."
        }
      ],
      "instrument_review": "The single evaluation documents grid-puzzle performance under the stated conditions. The explicit lack of repetition limits consistency claims and confidence in repeatable comparisons."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations held the listed conditions constant and reported score variation."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Controlled repetitions support consistency under the listed conditions and the stated stability definition. This evidence concerns the evaluated puzzles and does not establish consistency across different tasks or settings."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers tested score variation while holding the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed variation exceeds the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing documents a consistency problem under fixed conditions. The isolated 70% score does not adequately characterize the reported variation, which limits interpretation of comparisons based on a single run."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions provide no evidence that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no repeated scores supporting stability."
        }
      ],
      "instrument_review": "Installation documentation explains setup but adds no evaluation evidence. Repeatability remains unknown, and score interpretation remains limited to the reported grid-puzzle run."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish relative general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the narrow intended use. Exact-grid scoring and fixed instructions support interpretation of the reported difference, while repeatability and other resource controls are unspecified. Broader interpretation lacks evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better performance by A on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "The intended selection use exceeds the evidence supplied by the test's task coverage. The scores support the narrow observed comparison, but general-intelligence selection remains unsupported; repeatability and resource comparability are also unspecified."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Those scores alone do not establish improved real workshop decisions with A compared with B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checking, and a reported difference interval above zero support better correctness with A in the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision-correctness findings do not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The later preregistered randomized trial adds direct evidence relevant to choosing assistance for correctness in this workshop. Blinded checking and reported uncertainty strengthen the comparison. Findings remain limited to the studied conditions; safety, time, and transfer to other workshops are unestablished."
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was classified as Not established; explicit conflicting evidence was classified as Contradicted."
}
